package com.notsip.mobile
import android.content.Context
import okhttp3.*
import org.json.JSONObject
import java.util.UUID
class NotsipClient(private val ctx:Context){private val p=ctx.getSharedPreferences("notsip",Context.MODE_PRIVATE);private val http=OkHttpClient();fun baseUrl()=p.getString("base","http://10.0.2.2:8765")!!;fun setBaseUrl(v:String){p.edit().putString("base",v.trimEnd('/')).apply()};fun deviceId()=p.getString("device","android-${UUID.randomUUID()}")!!.also{p.edit().putString("device",it).apply()};fun setDeviceId(v:String){p.edit().putString("device",v).apply()};suspend fun pair(code:String){val body=JSONObject().put("code",code).put("device_id",deviceId()).put("name","Tecno Spark 30").put("platform","android").toString();val r=JSONObject(req("POST","/api/pair/consume",body));p.edit().putString("token",r.getString("token")).apply()};fun token()=p.getString("token","")!!;fun heartbeat(){req("POST","/api/devices/heartbeat?device_id=${deviceId()}&token=${token()}",null)};fun poll()=JSONObject(req("GET","/api/devices/${deviceId()}/commands?token=${token()}",null));fun result(id:String,status:String,result:JSONObject){req("POST","/api/devices/result",JSONObject().put("command_id",id).put("status",status).put("result",result).toString())};private fun req(m:String,path:String,body:String?):String{val b=body?.toRequestBody("application/json".toMediaType());val rb=Request.Builder().url(baseUrl()+path);if(m=="POST")rb.post(b?:"".toRequestBody())else rb.get();http.newCall(rb.build()).execute().use{if(!it.isSuccessful)throw RuntimeException("HTTP ${it.code}");return it.body!!.string()}}
}
